import * as Sentry from '@sentry/node';
import { nodeProfilingIntegration } from '@sentry/profiling-node';
import express from 'express';

// IMPORTANT: Initialize Sentry BEFORE any other imports/setup
Sentry.init({
  dsn: process.env.SENTRY_DSN!,
  environment: process.env.NODE_ENV ?? 'development',
  integrations: [nodeProfilingIntegration()],
  tracesSampleRate: 1.0,  // Capture 100% of transactions (reduce in prod)
  profilesSampleRate: 1.0,
});

const app = express();

// Add routes here...

// IMPORTANT: Sentry error handler must be AFTER routes and BEFORE other error handlers
Sentry.setupExpressErrorHandler(app);

// Example: manually capture an error with context
try {
  const result = await riskyOperation();
} catch (error) {
  Sentry.captureException(error, {
    extra: { userId: 'user-123', operation: 'riskyOperation' },
    tags: { feature: 'checkout' },
  });
  throw error;
}
